}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
 /// <param name = "_outboundProcess">_outboundProcess</param>
 /// <param name = "_acType">_acType</param>
 /// <param name = "_custVendAC">_custVendAC</param>
 /// <param name = "_ediAmount">_ediAmount</param>
 /// <param name = "_ediOriginId">_ediOriginId</param>
 /// <returns>AVAMSQTransformationDefinition</returns>
 public static AVAMSQTransformationDefinition     findExportFromProcessTOS(AVAMSQOutIntProcesses     _outboundProcess,
                                                           CustVendACType            _acType       = CustVendACType::Cust,
                                                           CustVendAC                _custVendAC   = '',
                                                           Amount                    _ediAmount = 0,
                                                           AVAMSQOriginId            _ediOriginId = '')
 {
     CustTable           custTable;
     AVATOSId            tosId;
     KCS_TOSTable        tosTable;
     AVAMSQTransformationDefinition  foundTransDefinition;

     if (_acType == CustVendACType::Vend)
     {
         return null;
     }

     if (_custVendAC)
     {

         foundTransDefinition = AVAMSQProcessingQueue::uploadExportFromProcessWithExceptionsTransDef(_outboundProcess,CustVendACType::Cust,_custVendAC,_ediAmount,_ediOriginId,_custVendAC);

         if (foundTransDefinition.RecId)
         {
             return foundTransDefinition;
         }
         select firstonly AccountNum, KCS_TOSId, recId from  custTable
             where custTable.AccountNum == _custVendAC;

         tosId = custTable.KCS_TOSId;

         select firstonly  TosId, ParentTosId,recId from
             tosTable where tosTable.TosId == tosId;

         while (tosTable.RecId)
         {

             foundTransDefinition = AVAMSQProcessingQueue::uploadExportFromProcessWithExceptionsTransDef(_outboundProcess,CustVendACType::Cust,tosTable.TosId,_ediAmount,_ediOriginId,_custVendAC);

             if (foundTransDefinition.RecId)
             {
                 break;
             }
             else
             {
                 tosId = tosTable.ParentTosId;
                 if (tosId)
                 {
                     select firstonly tosId, ParentTosId,RecId from tosTable
                         where tosTable.TosId == tosId;
                 }
                 else
                 {
                     break;
                 }
             }
         }
     }

     return foundTransDefinition;
 }

public static AVAMSQTransformationDefinition     findExportFromProcessTOSWithoutPatam(AVAMSQOutIntProcesses     _outboundProcess,
                                                          CustVendACType            _acType       = CustVendACType::Cust,
                                                          CustVendAC                _custVendAC   = '',
                                                          Amount                    _ediAmount = 0,
                                                          AVAMSQOriginId            _ediOriginId = '')
{
    CustTable           custTable;
    AVATOSId            tosId;
    KCS_TOSTable        tosTable;
    AVAMSQTransformationDefinition  foundTransDefinition;

    if (_acType == CustVendACType::Vend)
    {
        return null;
    }

    if (_custVendAC)
    {

        foundTransDefinition = AVAMSQProcessingQueue::uploadExportFromProcessWithExceptionsTransDefWithoutParam(_outboundProcess,CustVendACType::Cust,_custVendAC);

        if (foundTransDefinition.RecId)
        {
            return foundTransDefinition;
        }
        select firstonly AccountNum, KCS_TOSId, recId from  custTable
            where custTable.AccountNum == _custVendAC;

        tosId = custTable.KCS_TOSId;

        select firstonly  TosId, ParentTosId,recId from
            tosTable where tosTable.TosId == tosId;

        while (tosTable.RecId)
        {

            foundTransDefinition = AVAMSQProcessingQueue::uploadExportFromProcessWithExceptionsTransDefWithoutParam(_outboundProcess,CustVendACType::Cust,tosTable.TosId);

            if (foundTransDefinition.RecId)
            {
                break;
            }
            else
            {
                tosId = tosTable.ParentTosId;
                if (tosId)
                {
                    select firstonly tosId, ParentTosId,RecId from tosTable
                        where tosTable.TosId == tosId;
                }
                else
                {
                    break;
                }
            }
        }
    }

    return foundTransDefinition;
}

/// <summary>
/// defined from AVA
/// </summary>
/// <param name = "_outboundProcess">_outboundProcess</param>
/// <param name = "_refRecId">_refRecId</param>
/// <param name = "_acType">_acType</param>
/// <param name = "_custVendAC">_custVendAC</param>
/// <param name = "_refFieldName">_refFieldName</param>
/// <param name = "_filename">_filename</param>
/// <param name = "_DocNum">_DocNum</param>
/// <param name = "_ediAmount">_ediAmount</param>
/// <param name = "_ediOriginId">_ediOriginId</param>
/// <returns>AVAMSQQueueId</returns>
public static AVAMSQQueueId     uploadExportFromProcessTOS(AVAMSQOutIntProcesses     _outboundProcess,
                                                          str                       _refRecId,
                                                          CustVendACType            _acType       = CustVendACType::Cust,
                                                          CustVendAC                _custVendAC   = '',
                                                          str	                    _refFieldName = '',
                                                          Filename                  _filename     = '',
                                                          str                       _DocNum = '',
                                                          Amount                    _ediAmount = 0,
                                                          AVAMSQOriginId            _ediOriginId = '')
{
    AVAMSQTransformationDefinition transformationDefinition = AVAMSQProcessingQueue::findExportFromProcessTOS(_outboundProcess,_acType,_custVendAC,_ediAmount,_ediOriginId);
    AVAMSQQueueId           avaMSQQueueId;

    if (transformationDefinition.RecId)
    {
        avaMSQQueueId = AVAMSQProcessingQueue::insertIntoProcessQueue(transformationDefinition,
                                                                                    _refRecId,
                                                                                    _refFieldName,
                                                                                    _filename,
                                                                                    _DocNum);
    }

    return avaMSQQueueId;

}

/// <summary>
/// designed from AVA
/// </summary>
 /// <param name = "_outboundProcess">_outboundProcess</param>
 /// <param name = "_refRecId">_refRecId</param>
 /// <param name = "_acType">_acType</param>
 /// <param name = "_custVendAC">_custVendAC</param>
 /// <param name = "_refFieldName">_refFieldName</param>
 /// <param name = "_filename">_filename</param>
 /// <param name = "_DocNum">_DocNum</param>
 /// <param name = "_ediAmount">_ediAmount</param>
 /// <param name = "_ediOriginId">_ediOriginId</param>
 /// <param name = "_origCustAccount">_origCustAccount</param>
 /// <returns>AVAMSQQueueId</returns>
 public static AVAMSQQueueId uploadExportFromProcessWithExceptions(AVAMSQOutIntProcesses     _outboundProcess,
                                                                     str                       _refRecId,
                                                                     CustVendACType            _acType       = CustVendACType::Cust,
                                                                     CustVendAC                _custVendAC   = '',
                                                                     str	                      _refFieldName = '',
                                                                     Filename                  _filename     = '',
                                                                     str                       _DocNum = '', //-->AVA Osama  21-07-2017 added _filename
                                                                     //-->18.01.2023 frn ndx adjustment
                                                                     Amount                    _ediAmount = 0,
                                                                     AVAMSQOriginId            _ediOriginId = '',
                                                                     CustAccount               _origCustAccount = '')
                                                                         //<--18.01.2023 frn ndx adjustment
 {
     AVAMSQOutboundProcessToTransfDef       outboundProcessToTransDef;
     AVAMSQTransformationDefinition         transformationDefinition;
     AVAMSQCustVendAssignment               custVendAssignment;
     AVAMSQQueueId                          avaMSQQueueId;

     //-->AVA/FRN/15.09.2017/297
     if (_custVendAC)
     {
         //<--AVA/FRN/15.09.2017/297
         while select  outboundProcessToTransDef
             where outboundProcessToTransDef.OutboundProcesses == _outboundProcess
                 join transformationDefinition
                     where transformationDefinition.TransfDefId == outboundProcessToTransDef.TransfDefId
                             join custVendAssignment
                                 where custVendAssignment.OutboundEndpoint   == outboundProcessToTransDef.RecId
                                    && ((custVendAssignment.CustVendAC       == _custVendAC
                                    && custVendAssignment.CustVendACType     == _acType)
                                    || !_custVendAC)
             //-->18.01.2023 frn ndx adjustment
             && (custVendAssignment.NoNegativeValue == NoYes::No || (custVendAssignment.NoNegativeValue == NoYes::Yes && _ediAmount >=0))
             && (custVendAssignment.NoPositiveValue == NoYes::No || (custVendAssignment.NoPositiveValue == NoYes::Yes && _ediAmount <= 0))
             && (custVendAssignment.NoZeroValue     == NoYes::No || (custVendAssignment.NoZeroValue     == NoYes::Yes && _ediAmount !=0))
             && (custVendAssignment.OriginId == _ediOriginId)
             //<--18.01.2023 frn ndx adjustment
         {
             if (outboundProcessToTransDef)
             {
                 if (!AVACustVendAssignemtExceptions::checkIfExceptionsExist(custVendAssignment.RecId,_origCustAccount))
                 {
                     avaMSQQueueId = AVAMSQProcessingQueue::insertIntoProcessQueue(transformationDefinition,
                                                                                     _refRecId,
                                                                                     _refFieldName,
                                                                                     _filename,
                                                                                     _DocNum);
                 }
             }
         }
         //-->AVA/FRN/15.09.2017/297
     }
     else
     {
         while select  outboundProcessToTransDef
             where outboundProcessToTransDef.OutboundProcesses == _outboundProcess
                 join transformationDefinition
                     where transformationDefinition.TransfDefId == outboundProcessToTransDef.TransfDefId
         {
             if (outboundProcessToTransDef)
             {
                 avaMSQQueueId = AVAMSQProcessingQueue::insertIntoProcessQueue(transformationDefinition,
                                                                                 _refRecId,
                                                                                 _refFieldName,
                                                                                 _filename,
                                                                                 _DocNum);
             }
         }


     }
     //<--AVA/FRN/15.09.2017/297
     return avaMSQQueueId;
 }

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_outboundProcess">_outboundProcess</param>
/// <param name = "_acType">_acType</param>
/// <param name = "_custVendAC">_custVendAC</param>
/// <param name = "_ediAmount">_ediAmount</param>
/// <param name = "_ediOriginId">_ediOriginId</param>
/// <param name = "_origCustAccount">_origCustAccount</param>
/// <returns>AVAMSQTransformationDefinition</returns>
public static AVAMSQTransformationDefinition uploadExportFromProcessWithExceptionsTransDef(AVAMSQOutIntProcesses     _outboundProcess,
                                                                    CustVendACType            _acType       = CustVendACType::Cust,
                                                                    CustVendAC                _custVendAC   = '',
                                                                    //-->18.01.2023 frn ndx adjustment
                                                                    Amount                    _ediAmount = 0,
                                                                    AVAMSQOriginId            _ediOriginId = '',
                                                                    CustAccount               _origCustAccount = '')
                                                                        //<--18.01.2023 frn ndx adjustment
{
    AVAMSQOutboundProcessToTransfDef       outboundProcessToTransDef;
    AVAMSQTransformationDefinition         transformationDefinition;
    AVAMSQCustVendAssignment               custVendAssignment;
    AVAMSQTransformationDefinition         foundTransDefinition;

    //-->AVA/FRN/15.09.2017/297
    if (_custVendAC)
    {
        //<--AVA/FRN/15.09.2017/297
        while select  outboundProcessToTransDef
            where outboundProcessToTransDef.OutboundProcesses == _outboundProcess
                join transformationDefinition
                    where transformationDefinition.TransfDefId == outboundProcessToTransDef.TransfDefId
                            join custVendAssignment
                                where custVendAssignment.OutboundEndpoint   == outboundProcessToTransDef.RecId
                                   && ((custVendAssignment.CustVendAC       == _custVendAC
                                   && custVendAssignment.CustVendACType     == _acType)
                                   || !_custVendAC)
            //-->18.01.2023 frn ndx adjustment
            && (custVendAssignment.NoNegativeValue == NoYes::No || (custVendAssignment.NoNegativeValue == NoYes::Yes && _ediAmount >=0))
            && (custVendAssignment.NoPositiveValue == NoYes::No || (custVendAssignment.NoPositiveValue == NoYes::Yes && _ediAmount <= 0))
            && (custVendAssignment.NoZeroValue     == NoYes::No || (custVendAssignment.NoZeroValue     == NoYes::Yes && _ediAmount !=0))
            && (custVendAssignment.OriginId == _ediOriginId)
            //<--18.01.2023 frn ndx adjustment
        {
            if (outboundProcessToTransDef)
            {
                if (!AVACustVendAssignemtExceptions::checkIfExceptionsExist(custVendAssignment.RecId,_origCustAccount))
                {
                    foundTransDefinition.data(transformationDefinition);
                }
            }
        }
        //-->AVA/FRN/15.09.2017/297
    }
    else
    {
        while select  outboundProcessToTransDef
            where outboundProcessToTransDef.OutboundProcesses == _outboundProcess
                join transformationDefinition
                    where transformationDefinition.TransfDefId == outboundProcessToTransDef.TransfDefId
        {
            if (outboundProcessToTransDef)
            {
                foundTransDefinition.data(transformationDefinition);

            }
        }


    }
    //<--AVA/FRN/15.09.2017/297
    return foundTransDefinition;
}

public static AVAMSQTransformationDefinition uploadExportFromProcessWithExceptionsTransDefWithoutParam(AVAMSQOutIntProcesses     _outboundProcess,
                                                                    CustVendACType            _acType       = CustVendACType::Cust,
                                                                    CustVendAC                _custVendAC   = ''
                                                                    )

{
    AVAMSQOutboundProcessToTransfDef       outboundProcessToTransDef;
    AVAMSQTransformationDefinition         transformationDefinition;
    AVAMSQCustVendAssignment               custVendAssignment;
    AVAMSQTransformationDefinition         foundTransDefinition;

    //-->AVA/FRN/15.09.2017/297
    if (_custVendAC)
    {
        //<--AVA/FRN/15.09.2017/297
        while select  outboundProcessToTransDef
            where outboundProcessToTransDef.OutboundProcesses == _outboundProcess
                join transformationDefinition
                    where transformationDefinition.TransfDefId == outboundProcessToTransDef.TransfDefId
                            join custVendAssignment
                                where custVendAssignment.OutboundEndpoint   == outboundProcessToTransDef.RecId
                                   && ((custVendAssignment.CustVendAC       == _custVendAC
                                   && custVendAssignment.CustVendACType     == _acType)
                                   || !_custVendAC)

        {

            foundTransDefinition.data(transformationDefinition);

        }
        //-->AVA/FRN/15.09.2017/297
    }

    //<--AVA/FRN/15.09.2017/297
    return foundTransDefinition;
}
